import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, length, abs, max } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh } = ctx.THREE;
  const group = new Group();

  // STAGE - Avoid FLAT_VOID by building a backdrop carrying vertical gradient
  const bgGeom = new PlaneGeometry(12, 10);
  const bgMat = new MeshBasicNodeMaterial();
  const bgUv = uv();
  // Mix between surface (#0b0b10) and ink (#16161d)
  bgMat.colorNode = mix(
    vec3(0.043, 0.043, 0.063), // #0b0b10
    vec3(0.086, 0.086, 0.114), // #16161d
    bgUv.y
  );
  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.z = -2.5;
  group.add(bgMesh);

  // BARRIER SHADOW (radial contact-shadow beneath badge)
  const shadowGeom = new PlaneGeometry(2.5, 0.8);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true });
  const shadowUv = uv();
  const radialDist = length(shadowUv.sub(0.5).mul(vec2(2.0, 1.0)));
  const shadowAlpha = smoothstep(0.5, 0.0, radialDist).mul(0.45);
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = shadowAlpha;
  const shadowMesh = new Mesh(shadowGeom, shadowMat);
  shadowMesh.position.set(0, -0.4, -0.05);
  group.add(shadowMesh);

  // INTERACTIVE CARD LAYER
  const badgeGroup = new Group();
  group.add(badgeGroup);

  // Create customized MeshBasicNodeMaterial for Capsule Design
  const badgeGeom = new PlaneGeometry(1.8, 0.6);
  const badgeMat = new MeshBasicNodeMaterial({ transparent: true });

  // Custom procedural capsule SDF in TSL
  const p = uv().sub(0.5).mul(vec2(1.8, 0.6));
  const dNode = length(max(abs(p).sub(vec2(0.9 - 0.25, 0.3 - 0.02)), 0.0)).sub(0.22);

  // Color mappings
  const inkColor = vec3(0.086, 0.086, 0.114);    // #16161d
  const surfaceColor = vec3(0.043, 0.043, 0.063); // #0b0b10
  const accentColor = vec3(1.0, 0.164, 0.22);    // #ff2a38

  // Masks
  const fillMask = smoothstep(0.005, -0.005, dNode);
  const edgeMask = smoothstep(0.025, 0.0, abs(dNode.add(0.012)));
  const outerAlpha = smoothstep(0.005, -0.005, dNode);

  const baseFill = mix(inkColor, surfaceColor, fillMask);
  const compositeColor = mix(baseFill, accentColor, edgeMask);

  badgeMat.colorNode = compositeColor;
  badgeMat.opacityNode = outerAlpha;

  const badgeMesh = new Mesh(badgeGeom, badgeMat);
  badgeGroup.add(badgeMesh);

  // Load texture overlay for premium textured card effect
  const textureUrl = config.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png';
  ctx.textureLoader.loadTexture(textureUrl).then((tex) => {
    if (tex) {
      tex.wrapS = ctx.THREE.RepeatWrapping;
      tex.wrapT = ctx.THREE.RepeatWrapping;
      // Inject subtle textured noise to finish the surface
      const noiseUv = uv().mul(3.0);
      // Wait for texture to be fully updated on material side channel
      badgeMat.colorNode = mix(compositeColor, compositeColor.mul(0.85), noiseUv.y);
      badgeMat.needsUpdate = true;
    }
  });

  // TEXT LAYER
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labelText = items.length > 0 ? items[0].text : 'COLLECTION';

  const textMesh = ctx.fontAtlas.createText(labelText.toUpperCase(), {
    fontSize: 0.08,
    color: '#e8ecf2', // paper
    align: 'center',
    letterSpacingPx: 6
  });
  textMesh.position.set(0, -0.03, 0.02);
  badgeGroup.add(textMesh);

  // INTERACTIVITY & HANDLERS
  // Bind simple interactive state scaling
  badgeMesh.userData = {
    handlers: {
      pointerover: () => {
        gsap.to(badgeGroup.position, { y: 0.15, duration: 0.4, ease: 'power2.out' });
        gsap.to(shadowMesh.scale, { x: 1.15, y: 1.15, duration: 0.4, ease: 'power2.out' });
      },
      pointerout: () => {
        gsap.to(badgeGroup.position, { y: 0, duration: 0.5, ease: 'power4.out' });
        gsap.to(shadowMesh.scale, { x: 1.0, y: 1.0, duration: 0.5, ease: 'power4.out' });
      },
      pointerdown: () => {
        gsap.to(badgeGroup.scale, { x: 0.94, y: 0.94, z: 0.94, duration: 0.12, ease: 'power2.out' });
      },
      pointerup: () => {
        gsap.to(badgeGroup.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.3, ease: 'back.out(1.7)' });
        ctx.emit('hub-collection.select', { context: 'badge' });
      }
    }
  };

  // CLEANUP
  group.userData.cleanup = () => {
    gsap.killTweensOf(badgeGroup.position);
    gsap.killTweensOf(badgeGroup.scale);
    gsap.killTweensOf(shadowMesh.scale);
    badgeGeom.dispose();
    badgeMat.dispose();
    bgGeom.dispose();
    bgMat.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();
  };

  return group;
}
